<node TEXT="images, linked only" ID="ID_1537637948" CREATED="1739989935787" MODIFIED="1767706856713" TEXT_SHORTENED="true">
<hook URI="FreePlaneLearningAk_img/default_image.jpg" SIZE="1.0" NAME="ExternalObject"/>
<attribute_layout NAME_WIDTH="28.34646 pt" VALUE_WIDTH="28.34646 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Die Bilder sind nicht in der FreePlane-Datei selber gespeichert. Es ist lediglich ein relativer Link auf das Bild gespeichert.
    </p>
    <p>
      Darum empfiehlt es sich, die Bilder einer FreePlane-Map z.B: in einem Unterverzeichnis dieser FreePlane-Datei abzuspeichern.
    </p>
    <p>
      z.B: mit Name 'rsc', (=Ressourcen)<br/><br/>Beispiel:<br/>FreePLane\MyProj\MyProj.mm
    </p>
    <p>
      FreePLane\<span style="font-weight: bold;">MyProj</span>\<span style="font-weight: bold;">rsc</span>\bild1.jpg
    </p>
  </body>
</html></richcontent>
